function validate([deck]) {
  if (!Array.isArray(deck) || deck.length < 1 || deck.length > 1000) return 'deck needs 1 to 1000 cards.';
  if (deck.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each card is a whole number from 1 to 10^6.';
  if (new Set(deck).size !== deck.length) return 'All cards must be different.';
  return null;
}

