function deckRevealedIncreasing(deck) {
  const sorted = [...deck].sort((a, b) => a - b);
  const result = new Array(deck.length);
  const queue = [];
  for (let i = 0; i < deck.length; i++) {
    queue.push(i);
  }
  let head = 0;

  for (const card of sorted) {
    const slot = queue[head];
    head++;
    result[slot] = card;
    if (head < queue.length) {
      queue.push(queue[head]);
      head++;
    }
  }
  return result;
}

