function deckRevealedIncreasing(deck) {
  // Undo the ritual: hand the cards back from largest to smallest.
  // Undoing "reveal the top" puts the card on top; undoing "move top to bottom" brings the bottom card back to the top.
  const descending = deck.slice().sort((a, b) => b - a);
  const stack = [];
  for (const card of descending) {
    if (stack.length > 0) stack.unshift(stack.pop());
    stack.unshift(card);
  }
  return stack;
}

