function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 9);
  const limit = size === 'large' ? 1000000 : (rand() < 0.5 ? 30 : 1000000);
  const used = new Set();
  const deck = [];
  while (deck.length < n) {
    // On a repeat, step to the next free value so the loop always ends.
    let value = 1 + Math.floor(rand() * limit);
    while (used.has(value)) value = value % limit + 1;
    used.add(value);
    deck.push(value);
  }
  if (size === 'small' && rand() < 0.2) deck.sort((a, b) => a - b);
  return [deck];
}
